        Colors[ 0] := 'C71111'; // Red
        Colors[ 1] := 'C71111'; // Blue
        Colors[ 2] := '10802D'; // Green
        Colors[ 3] := 'EE55BA'; // Pink
        Colors[ 4] := 'F17D0E'; // Orange
        Colors[ 5] := 'F6F757'; // Yellow
        Colors[ 6] := '3F484E'; // Black
        Colors[ 7] := 'D6E1F0'; // White
        Colors[ 8] := '6B30BC'; // Purple
        Colors[ 9] := '72491E'; // Brown
        Colors[10] := '39E2DD'; // Cyan
        Colors[11] := '50F038'; // Lime
        Colors[12] := '6B2B3C'; // Maroon
        Colors[13] := 'ECC0D3'; // Rose
        Colors[14] := 'FFFEBE'; // Banana
        Colors[15] := '8397A7'; // Gray
        Colors[16] := '928776'; // Tan
        Colors[17] := 'EC7578'; // Coral
        clBody := Colors[Random(18)];
        clEyes := '95CADC';     // Light Blue
        for i := 0 to 5 do
            Colors[i] := clBody;

        K := 0.35;

        BodyRadius := K;
        BodyTop    := K;
        BodyBottom :=-K;

        LegsRadius := K / 3;
        LegsBottom :=-K * 1.75;
        LegsY := K * 2 / 3;

        GlassRadius := K * 0.9;
        GlassX := K * 0.35;
        GlassCut := (BodyRadius^2 - GlassRadius^2 + GlassX^2) / (2*GlassX);
        GlassTop := BodyTop + K * 0.5;
        GlassBottom := BodyTop - K * 0.5;

        BagTop := BodyTop;
        BagBottom := -K * 2 / 3;
        BagX := -K * 0.8;
        WX := K * 0.3;
        WY := K * 0.8;
        WZ := (BagTop - BagBottom) / 2;
        DWX := BagX - WX;
        DWZ := (BagTop + BagBottom) / 2;
